package com.remo.app

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Runs the shared corrections fixture: every platform lays the same
 * corrections and named places over the shared samples, and the activities,
 * outlier candidates and all-time places have to match the web implementation
 * (the fixture .expected.json file, regenerated by
 * apps/web/src/corrections-golden.test.ts).
 */
class CorrectionsFixtureTest {
    private fun fixture(name: String): File {
        var directory: File? = File("").absoluteFile
        while (directory != null) {
            val candidate = File(directory, "fixtures/timeline/$name")
            if (candidate.isFile) return candidate
            directory = directory.parentFile
        }
        error("fixtures/timeline/$name not found")
    }

    private val cases = JSONObject(fixture("corrections.cases.json").readText())
    private val expected = JSONObject(fixture("corrections.expected.json").readText())

    /** The sample day with the case's extra events, oldest first. */
    private fun eventsOf(day: String, extraEvents: JSONArray?): List<LogEntry> {
        val document = JSONObject(fixture("remo-timeline-$day.sample.json").readText())
        val events = document.getJSONArray("events")
        val combined = JSONArray()
        for (index in 0 until events.length()) combined.put(events.getJSONObject(index))
        for (index in 0 until (extraEvents?.length() ?: 0)) combined.put(extraEvents!!.getJSONObject(index))
        document.put("events", combined)
        return decodeTimelineImport(document.toString(), importedAt = 0L).sortedBy(LogEntry::startedAt)
    }

    private fun correctionsOf(array: JSONArray?): List<TimelineCorrection> = (0 until (array?.length() ?: 0)).mapNotNull { index ->
        val value = array!!.getJSONObject(index)
        val kind = timelineCorrectionKind(value.getString("kind")) ?: return@mapNotNull null
        TimelineCorrection(
            id = value.getString("id"),
            kind = kind,
            startedAt = value.getLong("startedAt"),
            endedAt = value.getLong("endedAt"),
            createdAt = value.getLong("createdAt"),
            source = correctionSource(value.optString("source")),
            deleted = value.optBoolean("deleted", false),
        )
    }

    private fun placesOf(array: JSONArray?): List<NamedPlace> = (0 until (array?.length() ?: 0)).mapNotNull { index ->
        val value = array!!.getJSONObject(index)
        val latitude = value.optDouble("latitude").takeIf(Double::isFinite) ?: return@mapNotNull null
        val longitude = value.optDouble("longitude").takeIf(Double::isFinite) ?: return@mapNotNull null
        val anchors = value.optJSONArray("anchors")?.let { anchors ->
            (0 until anchors.length()).map { anchorIndex ->
                val anchor = anchors.getJSONObject(anchorIndex)
                PlaceAnchor(anchor.getDouble("latitude"), anchor.getDouble("longitude"), anchor.optDouble("radiusMeters", DEFAULT_PLACE_RADIUS_METERS))
            }
        }.orEmpty()
        NamedPlace(
            id = value.getString("id"),
            name = value.getString("name"),
            latitude = latitude,
            longitude = longitude,
            updatedAt = 0L,
            deleted = value.optBoolean("deleted", false),
            radiusMeters = if (value.isNull("radiusMeters")) null else value.getDouble("radiusMeters"),
            anchors = anchors,
        )
    }

    @Test fun matchesTheCorrectedTimelinesEveryPlatformExpects() {
        val actualCases = cases.getJSONArray("cases")
        val expectedCases = expected.getJSONArray("cases")
        assertEquals(expectedCases.length(), actualCases.length())
        for (index in 0 until actualCases.length()) {
            val case = actualCases.getJSONObject(index)
            val item = expectedCases.getJSONObject(index)
            val label = item.getString("name")
            assertEquals(label, case.getString("name"))
            val day = case.getString("day")
            val events = eventsOf(day, case.optJSONArray("extraEvents"))
            val analysis = analyzeTimeline(events, TimelineAdjustments(
                corrections = correctionsOf(case.optJSONArray("corrections")),
                places = placesOf(case.optJSONArray("places")),
            ))
            val activities = buildTimelineActivities(events, analysis)
            val expectedActivities = item.getJSONArray("activities")
            assertEquals("$label activities", expectedActivities.length(), activities.size)
            activities.forEachIndexed { activityIndex, activity ->
                val expectedActivity = expectedActivities.getJSONObject(activityIndex)
                val activityLabel = "$label activity $activityIndex"
                assertEquals(activityLabel, expectedActivity.getString("kind"), activity.kind.name.lowercase())
                assertEquals(activityLabel, expectedActivity.getLong("startedAt"), activity.startedAt)
                assertEquals(activityLabel, expectedActivity.getLong("endedAt"), activity.endedAt)
                assertEquals(activityLabel, expectedActivity.getInt("photoCount"), activity.photos.size)
                if (activity.kind == TimelineActivityKind.MOVEMENT) {
                    assertEquals(activityLabel, expectedActivity.getLong("untrackedMs"), activity.untrackedMs)
                } else {
                    assertEquals(activityLabel, expectedActivity.getDouble("latitude"), activity.coordinate!!.latitude, 1e-5)
                    assertEquals(activityLabel, expectedActivity.getDouble("longitude"), activity.coordinate!!.longitude, 1e-5)
                    assertEquals(activityLabel, if (expectedActivity.isNull("placeId")) null else expectedActivity.getString("placeId"), activity.placeId)
                    assertEquals(activityLabel, expectedActivity.getBoolean("corrected"), activity.corrected)
                }
            }
            val expectedOutliers = item.getJSONArray("outliers")
            val outliers = findOutlierCandidates(analysis)
            assertEquals("$label outliers", expectedOutliers.length(), outliers.size)
            outliers.forEachIndexed { outlierIndex, outlier ->
                val expectedOutlier = expectedOutliers.getJSONObject(outlierIndex)
                assertEquals("$label outlier $outlierIndex", expectedOutlier.getLong("startedAt"), outlier.startedAt)
                assertEquals("$label outlier $outlierIndex", expectedOutlier.getLong("endedAt"), outlier.endedAt)
                val expectedIds = expectedOutlier.getJSONArray("eventIds")
                assertEquals(
                    "$label outlier $outlierIndex",
                    (0 until expectedIds.length()).map(expectedIds::getString),
                    outlier.eventIds,
                )
            }
        }
    }

    @Test fun matchesTheAllTimePlacesEveryPlatformExpects() {
        val allPlaces = cases.getJSONObject("allPlaces")
        val days = allPlaces.getJSONArray("days")
        val corrections = correctionsOf(allPlaces.getJSONArray("corrections"))
        val places = placesOf(allPlaces.getJSONArray("places"))
        val stays = (0 until days.length()).flatMap { index ->
            detectDayStays(eventsOf(days.getString(index), null), corrections)
        }
        val actual = buildAllTimeStayPlaces(stays, places)
        val expectedPlaces = expected.getJSONArray("allPlaces")
        assertEquals(expectedPlaces.length(), actual.size)
        actual.forEachIndexed { index, place ->
            val item = expectedPlaces.getJSONObject(index)
            val label = "allPlaces $index"
            assertEquals(label, if (item.isNull("placeId")) null else item.getString("placeId"), place.placeId)
            assertEquals(label, item.getDouble("latitude"), place.coordinate.latitude, 1e-5)
            assertEquals(label, item.getDouble("longitude"), place.coordinate.longitude, 1e-5)
            assertEquals(label, item.getInt("visitCount"), place.visits.size)
            assertEquals(label, item.getInt("dayCount"), place.dayCount)
            assertEquals(label, item.getLong("totalDurationMs"), place.totalDurationMs)
        }
    }

    @Test fun namedPlaceMatchesItsNearestAnchorAndDeletedPlacesNeverMatch() {
        val home = NamedPlace(
            id = "home", name = "Home", latitude = 33.5808, longitude = 130.3881, radiusMeters = 100.0,
            anchors = listOf(PlaceAnchor(33.5834, 130.3899, 60.0)),
        )
        val deleted = NamedPlace(id = "gone", name = "Gone", latitude = 33.58378, longitude = 130.39253, deleted = true)
        val match = matchPlace(listOf(home, deleted), com.google.android.gms.maps.model.LatLng(33.5835, 130.39))
        assertEquals("home", match?.place?.id)
        assertEquals(60.0, match?.anchor?.radiusMeters ?: 0.0, 0.0)
        assertEquals(null, matchPlace(listOf(deleted), com.google.android.gms.maps.model.LatLng(33.58378, 130.39253)))
        assertTrue(placeAnchors(home).size == 2)
    }
}
